UPDATE results SET statement_tex = 'Let $\psi$ be a primitive character and $0 < \theta < 1$. Suppose that for every $Y_0 \ge 1$ there is $Y \ge Y_0$ with
\[ \mathcal G_\psi(x) \le x^\theta \qquad \text{for all } x \in [Y, Y^{3/2}]. \]
For $k \ge 0$ and $\Re s > 1$ let $A_k(s) = \frac{(-1)^k}{k!}\,\mathcal H_\psi^{(k)}(s)$. Then there is $\sigma_0 > 2$ such that for every real $\sigma \ge \sigma_0$ there are a constant $C > 0$ and an infinite set $K$ of positive integers with
\[ \text{for all } k \in K \text{ and all } \tau \in \R: \qquad |A_k(\sigma + i\tau)| + \Re A_k(\sigma) \le C\,(\sigma - \theta)^{-k}. \]', statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-24 17:40:00', updated_by = 'claude' WHERE id = 123;
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '123', 3, 'quantifiers-8JT2-2026-11-24', '{"tag":"8JT2","type":"lemma","title":"One-sided bound for the Taylor coefficients","statement_tex":"Let $\\psi$ be a primitive character and $0 < \\theta < 1$. Suppose that for every $Y_0 \\ge 1$ there is $Y \\ge Y_0$ with\n\\[ \\mathcal G_\\psi(x) \\le x^\\theta \\qquad \\text{for all } x \\in [Y, Y^{3/2}]. \\]\nFor $k \\ge 0$ and $\\Re s > 1$ let $A_k(s) = \\frac{(-1)^k}{k!}\\,\\mathcal H_\\psi^{(k)}(s)$. Then there is $\\sigma_0 > 2$ such that for every real $\\sigma \\ge \\sigma_0$ there are a constant $C > 0$ and an infinite set $K$ of positive integers with\n\\[ \\text{for all } k \\in K \\text{ and all } \\tau \\in \\R: \\qquad |A_k(\\sigma + i\\tau)| + \\Re A_k(\\sigma) \\le C\\,(\\sigma - \\theta)^{-k}. \\]","section_id":104,"position":11,"listed":0,"aliases":["one-sided-taylor-bound"]}', 'claude');
UPDATE proofs SET body_tex = '\emph{Idea.} The numbers $A_k(z) = \frac{(-1)^k}{k!}\mathcal H_\psi^{(k)}(z)$ are the Taylor coefficients of $w \mapsto \mathcal H_\psi(z - w)$, so they grow like $d^{-k}$, where $d$ is the distance from $z$ to the nearest pole. On the line $\Re z = \sigma$ the hypothesis caps this growth at $(\sigma - \theta)^{-k}$. Hence no pole is closer to the line than $\sigma - \theta$, which is the claim $\Re\rho \le \theta$. The cap is only one-sided; this is where the positivity of real residues enters.

\emph{Step 1: upper bound.} Fix a real $\sigma \ge \sigma_0$, and let $C$ and $K$ be as in the \hyperref[8JT2]{one-sided bound}. Put $D_* = \sigma - \theta$. Then for all $k \in K$ and all $\tau \in \R$,
\[ |A_k(\sigma + i\tau)| + \Re A_k(\sigma) \le C\, D_*^{-k}. \tag{$*$} \]

\emph{Step 2: lower bound near a pole.} If $\rho$ is the only pole in a closed disc $\overline B(z, r)$, with residue $c$, then writing $\mathcal H_\psi(s) = \frac{c}{s - \rho} + h(s)$ and applying Cauchy''s estimate to $h$ gives
\[ A_k(z) = \frac{c}{(z - \rho)^{k+1}} + O(r^{-k}). \]
In particular $A_k(z) = O(r^{-k})$ if $\overline B(z, r)$ contains no pole.

\emph{Step 3: no pole closer than $D_*$.} Suppose some $\rho_0 \in Z$ has $\Re\rho_0 > \theta$, that is, $\sigma - \Re\rho_0 < D_*$. Let $D = \operatorname{dist}(\sigma, Z)$. Every pole is \hyperref[8JN4]{simple with nonzero residue}.

(a) \emph{Some pole $\rho_1$ has $\sigma - \Re\rho_1 < \min(D, D_*)$.} Take $z = \sigma + i\tau$ with $\tau$ close to $\Im\rho_1$. Its nearest pole $\rho$ has distance $d < \min(D, D_*)$, and moving $\tau$ slightly we may assume $\rho$ is unique, since $Z$ is \hyperref[8JS5]{locally finite} and two poles are equidistant from at most one point of the line. Choose $d < r < \min(D, D_*)$ with $\rho$ the only pole in $\overline B(z, r)$. As $\overline B(\sigma, r)$ has no pole, Step 2 gives
\[ |A_k(z)| + \Re A_k(\sigma) \ge |c|\, d^{-k-1} - O(r^{-k}), \]
which exceeds $C D_*^{-k}$ for large $k \in K$, contradicting $(*)$. We cannot argue at $z = \sigma$ itself: there the conjugate poles $\rho_1, \bar\rho_1$ are equally close and their contributions to $A_k(\sigma)$ may cancel.

(b) \emph{Every pole has $\sigma - \Re\rho \ge \min(D, D_*)$.} Applied to $\rho_0$ this gives $D < D_*$. A nearest pole $\rho$ to $\sigma$ satisfies $D = |\sigma - \rho| \ge \sigma - \Re\rho \ge D$, so $\rho = \beta = \sigma - D$ is real and the only pole at distance $D$. Its residue $c_\beta$ is positive by \hyperref[8JS7]{the corollary}. By Step 2 with $D < r < D_*$, and $(*)$ at $\tau = 0$,
\[ 2 c_\beta D^{-k-1} - O(r^{-k}) \le |A_k(\sigma)| + \Re A_k(\sigma) \le C\, D_*^{-k}, \]
which is false for large $k \in K$. Here the sign of $c_\beta$ is essential: with $c_\beta < 0$ the left side would be small and the one-sided bound $(*)$ would give no information.', body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-24 17:40:00', updated_by = 'claude' WHERE id = 102;
